func:
// SMART CLASSROOM MANUAL FAST (works with the ORIGINAL ESP32 firmware).
// Browser: publishes every click immediately. This node never waits for an ACK.
// ON->temperature/mode/fan edits: directly forwarded without a 3-second IR gap.
// OFF: immediate, cancels a delayed ON. OFF->ON: protected for 5 minutes.
// Import only ONE active Safety Flow; do not publish directly from the web to ESP32.
const TOP_WEB = 'spu/classroom/webapp/cmd';
const TOP_IR = 'spu/classroom/remote/air';
const TOP_ESP = 'spu/classroom/status';
const TOP_REPLY = 'spu/classroom/webapp/status';
const MIN_OFF_MS = 5 * 60 * 1000;        // adjust to manufacturer requirements
const RESTART_HOLD_MS = 5 * 60 * 1000;   // unknown OFF history after restart
const MAX_PENDING_MS = 6 * 60 * 1000;    // latest deferred ON expires after 6m
const MAX_MESSAGE_AGE_MS = 60 * 1000;   // ignore old browser commands
const DEVICE_STATUS_FRESH_MS = 75 * 1000;
const now = Date.now();
const bootAt = context.get('fastBootAt') || now;
let liveOnSinceBoot = context.get('freshOnSinceBoot') === true;
let s = context.get('manualFastSafetyV3');
if (!s || typeof s !== 'object') {
  s = {lastOffAt:0,lastForwarded:null,lastForwardedAt:0,pending:null,lastDevicePower:null,lastDeviceStatusAt:0};
}
// Pending requests are never replayed after a restart / redeploy.
if (s.pending && (!Number.isFinite(s.pending.createdAt) || s.pending.createdAt < bootAt)) s.pending = null;
const outIR=[], outFeedback=[], outDebug=[];
const emit = (id,stage,reason='',waitMs=0) => {
  if (!id) return;
  outFeedback.push({topic:TOP_REPLY,qos:0,retain:false,payload:JSON.stringify({
    requestId:id,stage,reason,waitSeconds:Math.ceil(Math.max(0,waitMs)/1000),at:new Date(now).toISOString()
  })});
};
const trace = (value) => outDebug.push({payload:value});
const valid = o => o && typeof o==='object' && !Array.isArray(o)
  && (o.POWER===0 || o.POWER===1)
  && Number.isInteger(o.TEMP) && o.TEMP>=21 && o.TEMP<=27
  && Number.isInteger(o.MODE) && o.MODE>=0 && o.MODE<=2
  && Number.isInteger(o.FAN) && o.FAN>=0 && o.FAN<=3
  && typeof o.REQUEST_ID==='string' && /^[A-Za-z0-9_-]{2,100}$/.test(o.REQUEST_ID)
  && (o.SENT_AT===undefined || (Number.isSafeInteger(o.SENT_AT) && o.SENT_AT>0));
const forward = (item) => {
  const cmd=item.cmd;
  // Metadata is stripped! Original ESP32 recognizes only upper-case fields.
  outIR.push({topic:TOP_IR,qos:0,retain:false,payload:JSON.stringify(cmd)});
  s.lastForwarded={...cmd};
  s.lastForwardedAt=now;
  if (cmd.POWER===0) {
    s.lastOffAt=now;
    liveOnSinceBoot=false;
    context.set('freshOnSinceBoot',false);
  }
  emit(item.id,'IR_FORWARDED','Node-RED forwarded to ESP32 MQTT topic; physical AC not verified');
  trace('IR_FORWARDED '+item.id+' POWER='+cmd.POWER+' TEMP='+cmd.TEMP);
};
const clearPending = (stage,reason) => {
  if (s.pending) {emit(s.pending.id,stage,reason);s.pending=null;}
};
const mayForwardOnNow = () => {
  // These are *commanded* / *reported* states, not physical AC proof.
  const commandedOnThisBoot = !!(s.lastForwarded && s.lastForwarded.POWER===1
    && s.lastForwardedAt>=bootAt && s.lastForwardedAt>s.lastOffAt);
  const espReportsOnNow = liveOnSinceBoot && s.lastDevicePower==='ON'
    && now-s.lastDeviceStatusAt<DEVICE_STATUS_FRESH_MS;
  // A recent OFF always overrides a possibly delayed ON report.
  const offWait = s.lastOffAt ? Math.max(0,MIN_OFF_MS-(now-s.lastOffAt)) : 0;
  // A restart may have lost the latest OFF if context was not flushed to disk.
  // We can skip the startup hold only when this boot has evidence of ON.
  const startWait = !commandedOnThisBoot && !espReportsOnNow
    ? Math.max(0,RESTART_HOLD_MS-(now-bootAt)) : 0;
  const waitMs = Math.max(offWait,startWait);
  return {waitMs,reason:offWait>=startWait && offWait>0?'Minimum OFF time':'Restart safety hold'};
};
const attemptPending = () => {
  if (!s.pending) return;
  const item=s.pending;
  if (now-item.createdAt>=MAX_PENDING_MS) {
    clearPending('EXPIRED','คำขอ ON หมดอายุ ไม่เปิดแอร์จากคำสั่งเก่า');return;
  }
  const gate=mayForwardOnNow();
  if (gate.waitMs>0) {
    // Only send a WAIT status when it first changes, not once per second.
    if (item.lastReason!==gate.reason) {
      emit(item.id,'WAITING_SAFETY',gate.reason,gate.waitMs);
      item.lastReason=gate.reason;
    }
    return;
  }
  s.pending=null;
  forward(item);
};
if (msg.topic===TOP_WEB) {
  // Old retained web requests must never actuate IR on subscribe/reconnect.
  if (msg.retain===true) {
    trace('Rejected retained web command');
  } else {
    let req=msg.payload;
    try {if (typeof req==='string') req=JSON.parse(req);} catch(_) {req=null;}
    if (req && req.ACTION==='STATUS' && typeof req.REQUEST_ID==='string'
        && /^[A-Za-z0-9_-]{2,100}$/.test(req.REQUEST_ID)) {
      // Original firmware STATUS reports self-state and does NOT send IR.
      outIR.push({topic:TOP_IR,payload:'STATUS',qos:0,retain:false});
      emit(req.REQUEST_ID,'IR_FORWARDED','STATUS request only: no IR transmission');
    } else if (!valid(req)) {
      emit(req && typeof req.REQUEST_ID==='string' ? req.REQUEST_ID : null,
        'REJECTED','Invalid POWER/TEMP/MODE/FAN/REQUEST_ID');
      trace('Invalid web command');
    } else if (req.SENT_AT!==undefined &&
        (now-req.SENT_AT>MAX_MESSAGE_AGE_MS || req.SENT_AT-now>120000)) {
      emit(req.REQUEST_ID,'EXPIRED','Old/future-dated browser command rejected');
    } else {
      const item={id:req.REQUEST_ID,createdAt:now,
        cmd:{POWER:req.POWER,TEMP:req.TEMP,MODE:req.MODE,FAN:req.FAN}};
      // OFF always wins and cancels an ON awaiting compressor protection.
      if (item.cmd.POWER===0) {
        clearPending('SUPERSEDED','ยกเลิก ON ที่รออยู่ เพราะผู้ใช้กด OFF');
        emit(item.id,'ACCEPTED','Manual OFF accepted');
        forward(item);
      } else {
        clearPending('SUPERSEDED','มีคำขอใหม่กว่า');
        emit(item.id,'ACCEPTED','Manual command accepted');
        const gate=mayForwardOnNow();
        if (gate.waitMs>0) {
          s.pending=item;attemptPending();
        } else {
          forward(item);
        }
      }
    }
  }
} else if (msg.topic===TOP_ESP) {
  // Retained status is only a cached device report, never a fresh boot proof.
  if (!msg.retain) {
    try {
      const d=typeof msg.payload==='string'?JSON.parse(msg.payload):msg.payload;
      if (d && (d.power==='ON'||d.power==='OFF')) {
        s.lastDevicePower=d.power;s.lastDeviceStatusAt=now;
        if (d.power==='ON' && !(s.lastOffAt && now-s.lastOffAt<MIN_OFF_MS)) {
          liveOnSinceBoot=true;
          context.set('freshOnSinceBoot',true);
        } else if (d.power==='OFF') {
          liveOnSinceBoot=false;
          context.set('freshOnSinceBoot',false);
        }
      }
    } catch(_) { /* LWT / Engine online is not a valid power report */ }
  }
} else if (msg.topic==='__tick') {
  attemptPending();
}
// Configure file-backed Node-RED contextStorage for persistence across restarts.
// Even without persistence, the fresh startup hold protects unknown OFF history.
context.set('manualFastSafetyV3',s);
return [outIR.length?outIR:null,outFeedback.length?outFeedback:null,outDebug.length?outDebug:null];

initialize:
// Executed on every Node-RED deploy/restart. A previously unflushed OFF
// must never make a restart bypass the compressor-protection startup hold.
context.set('fastBootAt', Date.now());
context.set('freshOnSinceBoot', false);
